import {dimensions} from './assessment-core.mjs';
import {reproductionState,reproductionStatuses,auditCounts,reproductionSummary,validateReproductionReport,startBlocker} from './reproduction-core.mjs';
const verdicts={within_tolerance:'参考均值在容差内',outside_tolerance:'超出参考容差',pass:'检查符合',fail:'发现矛盾',unknown:'缺少证据',review_required:'需人工核对',supported:'获得支持',not_supported:'未获支持',inconclusive:'证据不足'};
const number=v=>typeof v==='number'&&Number.isFinite(v)?v.toFixed(6).replace(/\.?0+$/,''):'未测';
export class ReproductionWorkspace{
 constructor(intake){this.i=intake;this.dimension='scope';this.error='';this.busy=false;this.timer=null;this.caseReport=null;this.inspecting=false;}
 render(p){const s=reproductionState(p),e=x=>this.i.esc(x),counts=auditCounts(s.audit),report=s.report,sum=reproductionSummary(report),blocked=startBlocker(s,this.i.h.mode());return `<section class="reproduction-workspace"><div class="assessment-intro"><div><h2>从实际材料执行完整实验</h2><p>先核验代码、数据与配置，再按冻结的阶段、种子和方法运行，最后查看独立指标与统计验收。</p></div><label class="btn">导入证据报告<input class="sr-only" type="file" accept=".json,application/json" data-reproduction-report></label></div>${this.error?`<p class="error-box" role="alert">${e(this.error)}</p>`:''}<button class="btn text" data-reproduction="public-case">${this.caseReport?'收起':'查看'}公开 CPU 验收案例</button>${this.caseReport?`<section class="public-case-evidence"><h2>LIBLINEAR · 独立公开案例</h2><p>此处展示 CI 归档证据，独立于当前项目；不写入当前论文的评估结果。</p>${this.report(this.caseReport,{source:'public_case'},reproductionSummary(this.caseReport),e)}</section>`:''}${s.stale?'<p class="info-strip">项目材料已变更。下方保留历史记录，需要重新核验才能关联本次材料。</p>':''}<section class="reproduction-plan"><h3>绑定本地实验计划</h3><p class="section-description">计划声明论文完整实验清单、实际文件指纹、构建方法、阶段依赖、运行矩阵和验收协议。</p><div class="field"><label for="reproduction-plan-path">工作区中的 plan.json 路径</label><div class="joined-field"><input id="reproduction-plan-path" data-reproduction-plan value="${e(s.plan_path)}" placeholder="runs/liblinear-input/plan.json"><button class="btn" data-reproduction="audit" ${this.busy||this.i.h.mode()!=='runtime'?'disabled':''}>${this.busy?'正在核验…':'核验实际材料'}</button></div></div>${this.i.h.mode()!=='runtime'?'<p class="info-strip">当前预览可查看导入的报告。读取文件、构建环境和执行实验需要本地工作台。</p>':''}<details><summary>如何准备一份可执行计划</summary><p>仓库的 examples/reproduction_smoke/plan.json 是自制工程样例；LIBLINEAR CPU 案例由 scripts/prepare_liblinear_case.py 生成。请把自己的论文、代码和数据放入本地工作区，按真实来源修改计划。</p><p>本地审计接口只读文件。开始执行后使用 Docker，不自动回退到主机执行；缺少 Docker 或环境构建失败会保留失败证据。</p></details></section>${s.audit?`<section class="reproduction-audit"><div class="assessment-intro"><div><h2>材料核验记录</h2><p>${counts.pass} 项检查符合 · ${counts.fail} 项矛盾 · ${counts.unknown} 项缺证据 · ${counts.review_required} 项需人工核对</p></div><button class="btn text" data-reproduction="export-audit">导出核验记录</button></div><div class="criteria-index reproduction-dimensions">${dimensions.map(([id,label])=>`<button class="criterion-item ${this.dimension===id?'selected':''}" data-reproduction-dimension="${id}" aria-pressed="${this.dimension===id}">${label}</button>`).join('')}</div><div class="audit-evidence-list">${s.audit.checks.filter(c=>c.dimension===this.dimension).map(c=>`<details><summary><strong>${e(verdicts[c.status]||c.status)}</strong> ${e(c.code)}</summary><p>${e(c.detail)}</p><pre>${e(JSON.stringify(c.evidence,null,2))}</pre></details>`).join('')||'<p class="assessment-empty">该项没有检查记录。</p>'}</div><p class="small-note">通过的文件检查不等于科学结论成立。未覆盖实验、缺少构建或统计证据继续保留。</p></section>`:''}<section class="reproduction-run"><div class="assessment-intro"><div><h2>实验任务与执行证据</h2><p>${s.job?`${reproductionStatuses[s.job.status]||e(s.job.status)} · 任务 ${e(s.job.id.slice(0,12))}`:'尚未提交完整实验任务。'}</p></div><div class="source-actions"><button class="btn primary" data-reproduction="start" ${this.busy||blocked?'disabled':''}>启动完整实验</button>${s.job?'<button class="btn" data-reproduction="refresh">刷新任务与报告</button>':''}${s.job&&['queued','running'].includes(s.job.status)?'<button class="btn" data-reproduction="cancel">停止实验</button>':''}</div></div>${blocked?`<p class="small-note">${e(blocked)}</p>`:''}${s.job?.error?`<p class="error-box">${e(s.job.error)}</p>`:''}${s.job?`<p>当前任务记录：${s.job.progress?.completed_runs??0} 次完成 · ${s.job.progress?.failed_runs??0} 次失败</p>`:''}${report?this.report(report,s,sum,e):'<p class="assessment-empty">尚无完整实验证据。材料登记、短时 probe 和未执行计划不生成完整实验结果。</p>'}</section></section>`;}
 report(r,s,sum,e){return `<div class="reproduction-report"><div class="assessment-intro"><div><h3>${s.source==='runtime'?'本地运行时返回的证据':s.source==='public_case'?'公开案例归档证据':'导入的执行记录'}</h3><p>${reproductionStatuses[r.status]} · ${sum.completed} / ${sum.expected??'未知'} 次计划运行完成 · ${sum.stages} 个已记录阶段</p></div><button class="btn text" data-reproduction="${s.source==='public_case'?'export-case':'export-report'}">导出当前报告</button></div>${s.source==='uploaded'?'<p class="info-strip">此报告由用户导入；网页展示其中的记录，尚未连接原执行主机核验来源。</p>':s.source==='public_case'?'<p class="info-strip">作者版本和划分偏差已保留；当前记录不覆盖 Figure 1 与 rcv1；额外控制没有进行最优参数搜索，不验证论文的效率结论。<a href="https://github.com/Gump111458785/ArtiCheck/actions/runs/40857463535" target="_blank" rel="noopener">查看 CI 来源</a></p>':''}<dl class="evaluation-facts"><div><dt>实际耗时</dt><dd>${typeof r.elapsed_seconds==='number'?r.elapsed_seconds.toFixed(2)+' 秒':'未测'}</dd></div><div><dt>环境重建</dt><dd>${r.levels?.environment_rebuilt?'已记录构建及镜像内验证':'未验证'}</dd></div><div><dt>子进程峰值 RSS</dt><dd>${typeof r.measurement?.max_child_rss_bytes==='number'?(r.measurement.max_child_rss_bytes/1024**2).toFixed(1)+' MiB':'未测'}</dd></div><div><dt>GPU 峰值显存</dt><dd>${r.measurement?.gpu_peak_memory_bytes==null?'未测':(r.measurement.gpu_peak_memory_bytes/1024**2).toFixed(1)+' MiB'}</dd></div><div><dt>计算费用估计</dt><dd>${r.cost?.compute_estimate_usd==null?'单价未知，无法估计':'$'+r.cost.compute_estimate_usd.toFixed(6)}</dd></div></dl>${r.errors?.length?`<p class="error-box">${e(r.errors.join('；'))}</p>`:''}<p class="small-note table-scroll-hint">在表格内横向滚动查看全部指标。</p><div class="scroll-table"><table class="full-table"><thead><tr><th>实验与方法</th><th>有效运行数</th><th>指标均值</th><th>样本标准差</th><th>参考值对照</th></tr></thead><tbody>${r.experiments.flatMap(exp=>Object.entries(exp.variants||{}).map(([id,v])=>`<tr><td>${e(exp.experiment_id)} / ${e(id)}<br><span class="small-note">${e(r.plan?.experiments?.find(x=>x.id===exp.experiment_id)?.metric?.key||'指标键未提供')} · 原始数值</span></td><td class="num">${e(v.n)}</td><td class="num">${number(v.mean)}</td><td class="num">${number(v.sample_std)}</td><td>${e(verdicts[v.reference_comparison?.status]||'无参考值')}</td></tr>`)).join('')||'<tr><td colspan="5">尚无可汇总的实验结果。</td></tr>'}</tbody></table></div>${r.experiments.map(exp=>`<section class="statistical-acceptance"><h3>${e(exp.experiment_id)} · 配对统计验收</h3>${exp.comparisons?.map(c=>`<p><strong>${e(c.method)} / ${e(c.other)}：${e(verdicts[c.status]||c.status)}</strong><br>配对种子 ${c.paired_seeds.length} 个 · 方向统一后的差值区间 ${c.confidence_interval?c.confidence_interval.map(number).join(' 至 '):'证据不足，未计算'}<br><span class="small-note">家族置信水平 ${typeof c.family_confidence==='number'?(c.family_confidence*100).toFixed(1)+'%':'未提供'}；按预注册种子配对，区间已做多重比较校正。</span></p><details><summary>统计方法与原始依据</summary><p>${e(c.reason)}</p><p>${e(c.methodology)}</p></details>`).join('')||'<p>没有预注册的比较，不能据此判断主要结论。</p>'}</section>`).join('')}<details><summary>逐次运行与阶段证据</summary>${r.runs.map((row,ri)=>`<details class="evidence-attachment"><summary>${e(row.experiment)} / ${e(row.variant)} / seed ${row.seed} · ${reproductionStatuses[row.status]||e(row.status)}</summary><p>实际指标 ${number(row.metric)} · ${row.independent_metric?'已有独立重算记录':'未记录独立重算'}</p>${row.stages?.map((stage,si)=>`<details data-reproduction-stage="${ri}:${si}" data-reproduction-source="${s.source}"><summary>${e(stage.id)} · ${reproductionStatuses[stage.status]||e(stage.status)} · ${typeof stage.elapsed_seconds==='number'?stage.elapsed_seconds.toFixed(2):'未测'} 秒</summary><pre data-stage-output></pre></details>`).join('')||''}</details>`).join('')}</details><p class="assessment-boundary">主要结论${r.levels?.conclusion?'有验收记录':'尚未完成验收'}；报告只覆盖所声明计划。费用是声明单价下的估计，RSS 是子进程测量，未测资源保持未知。</p></div>`;}
 async loadPublicCase(){this.caseReport=validateReproductionReport(await (await fetch('./samples/liblinear-reproduction.json')).json());return this.caseReport;}
 async refresh(p){const s=reproductionState(p);if(!s.job||this.i.h.mode()!=='runtime')return;s.job=await this.i.h.request('/api/reproduction/runs/'+encodeURIComponent(s.job.id));if(s.job.report_ready){s.report=validateReproductionReport(await this.i.h.request(s.job.report_url));s.source='runtime';}await this.i.save(p);this.i.h.render();}
 afterRender(){clearTimeout(this.timer);const p=this.i.current(),s=reproductionState(p);if(this.i.h.page()==='project'&&this.i.step==='reproduction'&&s.job&&['queued','running'].includes(s.job.status)&&this.i.h.mode()==='runtime'&&!this.inspecting)this.timer=setTimeout(()=>{if(this.i.current().id===p.id&&this.i.step==='reproduction')this.refresh(p).catch(error=>{this.error=error.message;this.i.h.render();});},3000);}
 bind(){document.addEventListener('toggle',event=>{const el=event.target;if(!el.matches?.('[data-reproduction-stage]'))return;this.inspecting=!!document.querySelector('[data-reproduction-stage][open]');if(el.open){const [ri,si]=el.dataset.reproductionStage.split(':').map(Number),r=el.dataset.reproductionSource==='public_case'?this.caseReport:reproductionState(this.i.current()).report;el.querySelector('[data-stage-output]').textContent=JSON.stringify(r.runs[ri].stages[si],null,2);}this.afterRender();},true);document.addEventListener('input',event=>{if(!event.target.hasAttribute('data-reproduction-plan'))return;const s=reproductionState(this.i.current());s.plan_path=event.target.value;s.audit=null;s.stale=true;this.i.save();});document.addEventListener('change',async event=>{if(!event.target.hasAttribute('data-reproduction-report')||!event.target.files?.[0])return;try{const file=event.target.files[0];if(file.size>10*1024**2)throw Error('报告最大 10 MB');const p=this.i.current(),s=reproductionState(p);s.report=validateReproductionReport(JSON.parse(await file.text()));s.source='uploaded';s.job=null;s.audit=null;await this.i.save(p);this.i.h.render();}catch(error){this.error=error.message;this.i.h.render();}});document.addEventListener('click',async event=>{const dimension=event.target.closest('[data-reproduction-dimension]');if(dimension){this.dimension=dimension.dataset.reproductionDimension;this.i.h.render();return;}const button=event.target.closest('[data-reproduction]');if(!button)return;const p=this.i.current(),s=reproductionState(p);this.error='';this.busy=true;try{switch(button.dataset.reproduction){case'public-case':this.caseReport=this.caseReport?null:await this.loadPublicCase();break;case'export-case':this.i.h.download('liblinear-cpu-evidence.json',JSON.stringify(this.caseReport,null,2));break;case'audit':s.audit=await this.i.h.request('/api/reproduction/audit',{plan_path:s.plan_path,paper_sha256:p.paper?.sha256,project_id:p.id,imported_snapshot:p.repository?.kind==='github'?p.repository:undefined});s.stale=false;break;case'start':{const reason=startBlocker(s,this.i.h.mode());if(reason)throw Error(reason);s.job=await this.i.h.request('/api/reproduction/runs',{audit_token:s.audit.audit_token});s.report=null;s.source='runtime';break;}case'refresh':await this.refresh(p);break;case'cancel':await this.i.h.request('/api/reproduction/runs/'+encodeURIComponent(s.job.id)+'/cancel',{});break;case'export-audit':this.i.h.download('reproduction-audit.json',JSON.stringify(s.audit,(k,v)=>k==='audit_token'?undefined:v,2));break;case'export-report':this.i.h.download('reproduction-report.json',JSON.stringify(s.report,null,2));break;}await this.i.save(p);}catch(error){this.error=error.message;}finally{this.busy=false;this.i.h.render();}});}
}
